export function timeout(ms: number) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

export type TPermissionResponse = {
  result?: string;
  message: 'success' | 'fail';
};

export const checkTrackTransparency = async () => {
  const result = await check(PERMISSIONS.IOS.APP_TRACKING_TRANSPARENCY);
  if (result === RESULTS.DENIED) {
    // The permission has not been requested, so request it.
    await request(PERMISSIONS.IOS.APP_TRACKING_TRANSPARENCY);
  }
  return {result: result, message: 'success'};
};

export const CheckVoicePermission = async (): Promise<TPermissionResponse> => {
  try {
    if (Platform.OS === 'ios') {
      let result = await check(PERMISSIONS.IOS.MICROPHONE);
      if (result !== 'granted') {
        result = await request(PERMISSIONS.IOS.MICROPHONE);
        return {result: result, message: 'success'};
      }
      return {result: result, message: 'success'};
    } else {
      const result = await request(PERMISSIONS.ANDROID.RECORD_AUDIO);
      return {result: result, message: 'success'};
    }
  } catch (error) {
    return {message: 'fail'};
  }
};

export function formatTimeMMSS(seconds: number) {
  const minutes = Math.floor(seconds / 60);
  const remainingSeconds = seconds % 60;

  // Pad the minutes and seconds with leading zeros if needed
  const formattedMinutes = minutes.toString().padStart(2, '0');
  const formattedSeconds = remainingSeconds.toString().padStart(2, '0');

  return `${formattedMinutes}:${formattedSeconds}`;
}

export function getCorrectAnswer(answer?: string | string[]) {
  if (typeof answer === 'string') {
    return answer;
  } else if (typeof answer === 'object') {
    return answer?.[1];
  }
  return '';
}

export function darkenColor(hex: string, percent: number) {
  const num = parseInt(hex.slice(1), 16);
  const r = Math.max(0, (num >> 16) - (255 * percent) / 100);
  const g = Math.max(0, ((num >> 8) & 0x00ff) - (255 * percent) / 100);
  const b = Math.max(0, (num & 0x0000ff) - (255 * percent) / 100);

  return `#${((1 << 24) | (r << 16) | (g << 8) | b).toString(16).slice(1)}`;
}

// Function to get a random element from t.question
export const getRandomQuestion = (questions: any[]) => {
  const randomIndex = Math.floor(Math.random() * questions.length);
  return questions[randomIndex];
};

// Function to shuffle an array using the Fisher-Yates algorithm
export const shuffleArray = (array: any[]) => {
  const shuffledArray = [...array]; // Create a copy of the array
  for (let i = shuffledArray.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffledArray[i], shuffledArray[j]] = [shuffledArray[j], shuffledArray[i]];
  }
  return shuffledArray;
};

export const trim = (s: any) =>
  typeof s === 'string' ? (s as string).trim() : s;

export const isSubArray = (answerSelected: any[], correctAnswer: any[]) => {
  if (!Array.isArray(answerSelected) || !Array.isArray(correctAnswer)) {
    return false;
  }
  return answerSelected.every(answer =>
    correctAnswer.map(e => trim(e)).includes(trim(answer)),
  );
};

export function arraysEqualWithExactItem<T>(a: T[], b: T[]): boolean {
  if (a.length !== b.length) {
    return false;
  }
  return a.every((val, index) => val === b[index]);
}

export const isMMSS = (str: string) => {
  const regex = /^([0-5][0-9]):([0-5][0-9])$/;

  // Example usage
  const word = str;
  const isMatch = regex.test(word);

  return isMatch;
};

export const splitChineseWithFilter = (sentence: string): string[] => {
  return Array.from(sentence).filter(
    char =>
      /\p{Script=Han}/u.test(char) || // Keep Chinese characters
      /\p{N}/u.test(char) || // Keep numbers
      /\p{L}/u.test(char), // Keep letters
  );
};
/**
 * Sorts an array of AppEntity objects alphabetically by app_name (case insensitive)
 */
export const sortAppsByName = (apps: AppEntity[]): AppEntity[] => {
  return [...apps].sort((a, b) =>
    a.app_name.localeCompare(b.app_name, undefined, {sensitivity: 'base'}),
  );
};

export const splitTextContent = (sentence: string, data: string) => {
  const content = sentence;
  const list = ` ${data} `.split(content ?? '-.-');
  return list.flatMap((e, i) => {
    if (i === list.length - 1) {
      return e;
    }
    return [e, content];
  });
};
