import React, {
  useState,
  useImperativeHandle,
  forwardRef,
  ForwardRefRenderFunction,
  useMemo,
} from 'react';
import {View, Text, TouchableOpacity, StyleSheet} from 'react-native';
import {scale, verticalScale} from 'react-native-size-matters';
import {COLORS} from 'src/core/presentation/constants/colors';
import {FontFamily} from 'src/core/presentation/hooks/useFonts';
import ScrollIndicator from './ScrollIndicator';
import {assets} from 'src/core/presentation/utils';
import FastImage from 'react-native-fast-image';
import {useLessonStore} from '../stores/LessonStore/useGetPostsStore';
import useHomeStore from 'src/home/presentation/stores/useHomeStore';

interface SelectionAnswersQuestionProps {
  question: React.ReactNode;
  answer: string[];
  answerBuilder?: (text: string) => React.ReactNode;
  isShowCorrectContainer: boolean;
  isAnswerCorrect: boolean;
  onSelectAnswer: (selected: string[]) => void;
  learningTimer: number;
  isKeyboard?: boolean;
  isSelectOne?: boolean;
}

export interface SelectionAnswersQuestionRef {
  getSelectedAnswers: () => string[];
  resetAnswerSelected: () => void;
}

const KeyboardNumber: ForwardRefRenderFunction<
  SelectionAnswersQuestionRef,
  SelectionAnswersQuestionProps
> = (props, ref) => {
  const {
    question,
    answer,
    answerBuilder,
    isShowCorrectContainer,
    isAnswerCorrect,
    onSelectAnswer,
    learningTimer,
    isKeyboard,
    isSelectOne,
  } = props;

  const [answerSelected, setAnswerSelected] = useState<string[]>([]);
  const {getSetting} = useLessonStore();
  const {lessonSetting} = useHomeStore();

  const settings = useMemo(
    () => getSetting(lessonSetting),
    [getSetting, lessonSetting],
  );

  useImperativeHandle(ref, () => ({
    getSelectedAnswers: () => answerSelected,
    resetAnswerSelected: () => setAnswerSelected([]),
  }));

  const handleSelectAnswer = (e: string) => {
    if (isSelectOne) {
      setAnswerSelected(_ => {
        const newSelected: string[] = [e];
        onSelectAnswer(newSelected);
        return newSelected;
      });
      return;
    }
    if (isKeyboard) {
      setAnswerSelected(prev => {
        const newSelected = [...prev, e];
        onSelectAnswer(newSelected);
        return newSelected;
      });
    } else {
      setAnswerSelected(prev => {
        const newSelected = prev.includes(e)
          ? prev.filter(item => item !== e)
          : [...prev, e];
        onSelectAnswer(newSelected);
        return newSelected;
      });
    }
  };

  return (
    <View style={[styles.boxSelected]}>
      <View style={styles.wrapCharContainer}>
        {question}
        <TouchableOpacity
          style={styles.deleteContainer}
          onPress={() => {
            setAnswerSelected([]);
            onSelectAnswer([]);
          }}>
          <FastImage
            resizeMode="contain"
            source={assets.icon_delete}
            style={[{width: scale(20), height: scale(20)}]}
          />
        </TouchableOpacity>
      </View>
      <ScrollIndicator
        indicatorContainerColor={settings.backgroundButtonColor}
        indicatorColor={settings.backgroundButtonColor}>
        <View style={[styles.wapper, {width: '100%'}]}>
          {answer?.map((e, i) => {
            const bg =
              Array.isArray(answerSelected) &&
              answerSelected.includes(e) &&
              answerSelected.length
                ? isShowCorrectContainer && !isAnswerCorrect
                  ? '#F28759'
                  : '#66C270'
                : '#F2B559';

            return (
              <TouchableOpacity
                key={i}
                onPress={() => handleSelectAnswer(e)}
                disabled={
                  e === '.' &&
                  (answerSelected.length === 0 || answerSelected.includes('.'))
                }
                style={[
                  styles.boxVowel,
                  {
                    backgroundColor: bg,
                    width: scale(29),
                    height: scale(41),
                    margin: scale(4), // Add spacing for clarity
                    paddingHorizontal: scale(4),
                  },
                ]}>
                {answerBuilder ? (
                  answerBuilder(e)
                ) : (
                  <Text style={[styles.textVowel]}>{e}</Text>
                )}
              </TouchableOpacity>
            );
          })}
        </View>
      </ScrollIndicator>
      {learningTimer !== 0 && (
        <View
          style={[
            styles.boxSelected,
            {
              position: 'absolute',
              zIndex: 999,
              width: '100%',
              opacity: 0.7,
              height: '100%',
            },
          ]}
        />
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  boxSelected: {
    // Add your styles here
    backgroundColor: COLORS.WHITE_FBF8CC,
    height: verticalScale(220),
    flex: 1,
    borderRadius: scale(30),
    justifyContent: 'center',
    alignItems: 'center',
  },
  wrapCharContainer: {
    // Add your styles here
    flexDirection: 'row',
    alignItems: 'center',
    width: '80%',
    justifyContent: 'center',
  },
  fonts_SVN_Neu: {
    // Add your styles here
    fontFamily: FontFamily.SVNNeuzeitRegular,
  },
  textQuestion: {
    // Add your styles here
    fontSize: verticalScale(34),
    textAlign: 'center',
    color: COLORS.BLUE_258F78,
  },
  textGreen: {
    // Add your styles here
    color: COLORS.BLUE_258F78,
  },
  mt8: {
    // Add your styles here
    marginTop: verticalScale(8),
  },
  wapper: {
    // Add your styles here
    marginTop: scale(8),
    flexDirection: 'row',
    justifyContent: 'center',
    alignSelf: 'center',
    flexWrap: 'wrap', // Add this to enable wrapping
  },
  fill: {
    // Add your styles here
    flex: 1,
  },
  boxVowel: {
    // Add your styles here
    width: scale(56),
    height: scale(56),
    borderRadius: scale(10),
    justifyContent: 'center',
    alignItems: 'center',
    marginHorizontal: scale(4),
    marginVertical: scale(4),
  },
  textVowel: {
    // Add your styles here
    fontFamily: FontFamily.SVNCherishMoment,
    color: COLORS.WHITE_FBF8CC,
    fontSize: verticalScale(20),
    flexWrap: 'wrap',
  },
  deleteContainer: {
    padding: scale(8),
  },
});

export default forwardRef(KeyboardNumber);
