import {StyleSheet, Text, View} from 'react-native';
import React from 'react';
import IconArrowFill from 'assets/svg/IconArrowFill';
import useGlobalStyle from 'src/core/presentation/hooks/useGlobalStyle';
import ItemCard, {ItemCardProps} from '../ItemCard';
import {scale} from 'react-native-size-matters';
import {COLORS} from 'src/core/presentation/utils/colors';
import {ScrollView} from 'react-native-gesture-handler';
import {useI18n} from 'src/core/presentation/hooks/useI18n';

const ListBlockedApps = ({
  listApp,
  setTabBody,
  selectedApp,
}: {
  listApp: {
    id: string;
    name: string;
    icon: any;
    itemCardProps: Omit<ItemCardProps, 'Icon'>;
  }[];
  setTabBody: (id: string) => void;
  selectedApp: string;
}) => {
  const globalStyle = useGlobalStyle();
  const i18n = useI18n();

  return (
    <View style={[styles.rowBetween, styles.rowHCenter]}>
      <View style={[styles.arrowLeft]}>
        <IconArrowFill />
      </View>
      <ScrollView horizontal style={[styles.fill]}>
        {listApp.length ? (
          listApp.map(t => (
            <>
              <ItemCard
                key={t.id}
                Icon={t.icon}
                isFocus={selectedApp === t.name}
                name={t.name}
                onPress={() => setTabBody(t.name)}
                iconFocusColor="#F2B559"
                backgroundFocusColor="#FBF8CC"
                borderWidth={3}
                space={4}
                size={85}
                {...t?.itemCardProps}
              />
              <View style={{width: scale(10)}} />
            </>
          ))
        ) : (
          <View
            style={{
              width: '100%',
              alignItems: 'center',
            }}>
            <Text style={[globalStyle.txtNote, {color: COLORS.WHITE}]}>
              {i18n.t('lesson.screens.Parent.noBlockedApps')}
            </Text>
          </View>
        )}
      </ScrollView>
      <View style={[styles.arrowRight]}>
        <IconArrowFill type="right" />
      </View>
    </View>
  );
};

export default ListBlockedApps;

const styles = StyleSheet.create({
  fill: {
    flex: 1,
  },
  rowBetween: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    width: '100%',
  },
  rowHCenter: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  arrowRight: {
    marginLeft: scale(8),
  },
  arrowLeft: {
    marginRight: scale(8),
  },
});
