import React from 'react';
import {View, Text, TouchableOpacity, StyleSheet} from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
} from 'react-native-reanimated';
import {scale} from 'react-native-size-matters';
import {CustomTextStyle} from 'src/core/presentation/constants/typography';
import {IMergedData} from './ListSubject';

const SubjectItem = ({
  item,
  animatedStyle,
  onSelectSubject,
}: {
  item: IMergedData;
  animatedStyle: any;
  onSelectSubject: (item: IMergedData) => void;
}) => {
  const scaleItem = useSharedValue(1);

  const itemAnimatedStyle = useAnimatedStyle(() => {
    return {
      transform: [
        {scale: scaleItem.value},
        // {translateX: offsetX.value},
        // {translateY: offsetY.value},
      ],
    };
  });

  const handlePress = () => {
    // if (scaleItem.value === 1) {
    //   //   scaleItem.value = withSpring(WIDTH_SCREEN / scale(192)); // Assuming itemWidth is the original width of the item
    //   offsetX.value = withSpring(WIDTH_SCREEN / 2 - scale(192) / 2);
    //   offsetY.value = withSpring(HEIGHT_SCREEN / 2 - scale(192) / 2); // Assuming itemHeight is the original height of the item
    // } else {
    //   scaleItem.value = withSpring(1);
    //   offsetX.value = withSpring(0);
    //   offsetY.value = withSpring(0);
    // }
    if (item.isActive) {
      onSelectSubject(item);
    }
    // scaleItem.value = withSpring(1.5, {damping: 5}, () => {
    //   runOnJS(onSelectSubject)(item);
    // });
  };

  return (
    <Animated.View
      key={item.id}
      style={[styles.contentContainer, animatedStyle, itemAnimatedStyle]}>
      {item.position === 'right' && <View style={[{height: scale(152)}]} />}
      <TouchableOpacity
        style={[
          item.position === 'right'
            ? styles.rightContentContainer
            : styles.leftContentContainer,
          {backgroundColor: item.bgc},
        ]}
        hitSlop={{top: 100, bottom: 100, left: 20, right: 20}}
        onPress={() => handlePress()}>
        <Text
          allowFontScaling
          adjustsFontSizeToFit
          numberOfLines={1}
          style={[styles.itemTitle, {color: item.textColor}]}>
          {item.name}
        </Text>
      </TouchableOpacity>
    </Animated.View>
  );
};

const styles = StyleSheet.create({
  contentContainer: {
    flex: 1,
    flexDirection: 'row',
  },
  leftContentContainer: {
    height: scale(152),
    width: scale(152),
    justifyContent: 'center',
    alignItems: 'center',
    borderRadius: 999,
  },
  rightContentContainer: {
    height: scale(152),
    width: scale(152),
    justifyContent: 'center',
    alignItems: 'center',
    borderRadius: 999,
    position: 'absolute',
    right: 0,
  },
  itemTitle: {
    ...CustomTextStyle.h1_SVNCherishMoment,
    textTransform: 'uppercase',
  },
});

export default SubjectItem;
