import {usePopupTrialMode} from '../hooks/popup/usePopupTrialMode';

export type RouteParamsDone = {
  totalResult: TResult[];
  colorBgBookView?: string;
  backgroundAndie: React.ImageSourcePropType | string;
  andieImage: React.ImageSourcePropType | string;
  title: string;
  note: string;
  isMiniTest?: boolean;
  countTime?: string;
  moduleName?: string;
  lessonName?: string;
  partName?: string;
  noMiniTest?: boolean;
  type?: string;
  module?: Task;
  subjectId?: string;
};

const DoneLessonScreen = observer(({}) => {
  const route = useRoute<RouteProp<{param: RouteParamsDone}>>()?.params;

  const totalResultLength = route.totalResult?.length || 0;
  const totalCorrectAnswer =
    route.totalResult.filter((item: TResult) => item.status === 'completed')
      ?.length || 0;
  const styleHook = useGlobalStyle();
  const lessonStore = lessonModuleContainer.getProvided(LessonStore);
  const homeStore = useHomeStore();
  const authStore = useAuthenStore();
  const popupHook = usePopupTrialMode();

  const {deviceToken, selectedChild, getUserProfile, setSelectedChild} =
    useAuthenticationStore();
  const [isShowWatchAds, setIsShowWatchAds] = useState(false);
  const [isShowGotReward, setIsShowGotReward] = useState(false);
  const [isShowOnBoard, setIsShowOnBoard] = useState(false);

  const i18n = useI18n();

  useGetUserSetting(deviceToken, selectedChild?._id ?? '', lessonStore);
  const ggadsHook = useGoogleAdsmob();

  const onEarnReward = useCallback(
    async (reward?: RewardedAdReward) => {
      setIsShowWatchAds(false);
      setIsShowGotReward(true);
      if (reward) {
        lessonStore.changeChildrenPointFlower({
          childId: selectedChild?._id ?? '',
          point: 1,
        });

        const profile = await getUserProfile();
        const currentChild = profile.data.children.find(
          child => selectedChild?._id === child._id,
        );

        if (currentChild) {
          setSelectedChild(currentChild);
        }
      }
    },
    [getUserProfile, lessonStore, selectedChild?._id, setSelectedChild],
  );

  const isSuccess = useMemo(() => {
    const blockedModule = lessonStore.blockedModules?.find(
      module => module.moduleId === route.module?.lessonId,
    );

    if (route.isMiniTest && blockedModule) {
      // * nếu check ra mini test
      if (
        blockedModule?.percent <=
        (totalCorrectAnswer / totalResultLength) * 100
      ) {
        // * nếu ko đủ điểm unlock
        return true;
      } else {
        return false;
      }
    } else {
      // * nếu ko phải mini test
      return true;
    }
  }, [
    lessonStore.blockedModules,
    route.isMiniTest,
    route.module,
    totalCorrectAnswer,
    totalResultLength,
  ]);

  const onUnlockAppSetting = useCallback(async () => {
    if (isSuccess) {
      await unBlockApps();
      lessonStore.changeBlockedAnonymousListAppSystem(undefined);
      lessonStore.resetListAppSystem();
      Toast.show({
        type: 'success',
        text1: i18n.t('lesson.screens.Modules.appsUnlocked'),
      });
    } else {
      Toast.show({
        type: 'error',
        text1: i18n.t('lesson.screens.Modules.resultNotEnough'),
      });
    }
  }, [i18n, isSuccess, lessonStore]);

  const onShowBuyNewModule = useCallback(async () => {
    const userModule = await lessonStore.handleGetUserModule(
      homeStore.listModule,
      [0],
    );

    const allModule = await lessonStore.handleGetModulesChildren({
      childrenId: authStore.selectedChild?._id ?? '',
    });

    const purchasedModules = (allModule as unknown as Module[]).filter(module =>
      userModule.some(um => um._id === module._id),
    );

    const countFinishedModule = purchasedModules.filter(
      module => module.progressOfChildren > 0,
    );

    if (countFinishedModule.length === purchasedModules.length) {
      // TODO: show popup buy new module
      popupHook.handleToggleBuyMoreModulePopup();
      return;
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [authStore.selectedChild?._id, homeStore, lessonStore]);

  const onSubmit = useCallback(() => {
    if (route.noMiniTest) {
      lessonStore.setTrainingCount(TRAINING_COUNT);
      resetNavigator(STACK_NAVIGATOR.HOME.HOME_SCREEN);

      setTimeout(() => {
        lessonStore.setCurrentQuestion(undefined);
      }, 1000);
      return;
    }
    if (route.isMiniTest) {
      lessonStore.setTrainingCount(TRAINING_COUNT);
      lessonStore.setCurrentQuestion(undefined);
      setTimeout(() => {
        resetNavigator(STACK_NAVIGATOR.HOME.HOME_SCREEN);
      }, 0);
    } else {
      if (lessonStore.trainingCount === 0) {
        // * nếu part tiếp theo là mini test thì show màn loading
        setIsShowOnBoard(true);
        setTimeout(() => {
          goBack();
        }, 2000);
      } else {
        goBack();
      }
    }
  }, [lessonStore, route.isMiniTest, route.noMiniTest]);

  const onReceiveReward = useCallback(() => {
    setIsShowGotReward(false);
    onSubmit();
  }, [onSubmit]);

  const onNext = useCallback(() => {
    if (route.isMiniTest) {
      onSubmit();
      return;
    }
    console.log(
      '🛠 LOG: 🚀 --> -----------------------------------------------🛠 LOG: 🚀 -->',
    );
    console.log('🛠 LOG: 🚀 --> ~ onNext ~ ggadsHook:', ggadsHook);
    console.log(
      '🛠 LOG: 🚀 --> -----------------------------------------------🛠 LOG: 🚀 -->',
    );

    if (ggadsHook.reward === undefined && !ggadsHook.loaded) {
      onReceiveReward();
      return;
    }
    setIsShowWatchAds(true);
  }, [ggadsHook, onReceiveReward, onSubmit, route.isMiniTest]);

  const onWatchRewardAds = useCallback(() => {
    ggadsHook.showAds?.();
  }, [ggadsHook]);

  useEffect(() => {
    if (ggadsHook.reward && ggadsHook.isClosed && ggadsHook.isEarnedReward) {
      onEarnReward?.(ggadsHook.reward);
    }
  }, [
    ggadsHook.isClosed,
    ggadsHook.isEarnedReward,
    ggadsHook.reward,
    onEarnReward,
  ]);

  useEffect(() => {
    if (ggadsHook.reward && ggadsHook.isClosed && !ggadsHook.isEarnedReward) {
      onSubmit();
    }
  }, [
    ggadsHook.isClosed,
    ggadsHook.isEarnedReward,
    ggadsHook.reward,
    onEarnReward,
    onSubmit,
  ]);

  useEffect(() => {
    if (route.isMiniTest) {
      onUnlockAppSetting();
      onShowBuyNewModule();
    }
  }, [onShowBuyNewModule, onUnlockAppSetting, route.isMiniTest]);

  useEffect(() => {
    const backHandler = BackHandler.addEventListener(
      'hardwareBackPress',
      () => false,
    );
    return () => backHandler.remove();
  }, []);

  if (!isSuccess) {
    return (
      <View style={styles.container}>
        <ImageBackground
          style={styles.titleContainer}
          source={
            typeof route.backgroundAndie === 'string'
              ? {uri: route.backgroundAndie}
              : route.backgroundAndie
          }
          resizeMode="cover">
          <View style={styles.overlayBgImage} />

          <HeaderLesson
            lessonName={route.lessonName}
            module={route.moduleName}
            part={route.partName}
          />

          <Text
            style={[
              styleHook.txtWord,
              styles.text,
              {color: route.colorBgBookView},
            ]}>
            OH NOO !!!
          </Text>
          <Image
            source={
              typeof route.andieImage === 'string'
                ? {uri: route.andieImage}
                : route.andieImage
            }
            style={{height: scale(200), width: scale(200)}}
            resizeMode="contain"
          />
        </ImageBackground>
        <BookView
          style={styles.achievementContainer}
          contentStyle={styles.content}
          colorBg={COLORS.YELLOW_F2B559}
          imageBackground={assets.bee_bg}>
          <View style={styles.achievementContent}>
            <View style={styles.wrapperContent}>
              <Text style={[styleHook.txtModule, styles.contentTitle]}>
                {'UNSUCCESSFUL'} !!!
              </Text>
              <Text
                style={[styleHook.txtNote, styles.contentDescription]}
                textBreakStrategy="balanced">
                {i18n.t('lesson.screens.Modules.sorryMobilize')}
              </Text>
            </View>
          </View>
          <View style={styles.wrapperButton}>
            <TouchableOpacity
              onPress={onSubmit}
              style={[
                styles.button,
                !isSuccess && {backgroundColor: route.colorBgBookView},
              ]}>
              <Text style={[styleHook.txtButton, styles.textBtn]}>
                {i18n.t('lesson.screens.Modules.next')}
              </Text>
            </TouchableOpacity>
          </View>
        </BookView>
      </View>
    );
  }

  return (
    <GoogleAdsmobProvider>
      <View style={styles.container}>
        <ImageBackground
          style={styles.titleContainer}
          source={
            typeof route.backgroundAndie === 'string'
              ? {uri: route.backgroundAndie}
              : route.backgroundAndie
          }
          resizeMode="cover">
          <View style={styles.overlayBgImage} />
          <HeaderLesson
            lessonName={route.lessonName}
            module={route.moduleName}
            part={route.partName}
            color={route.colorBgBookView}
          />
          <Text
            style={[
              styleHook.txtWord,
              styles.text,
              {color: route.colorBgBookView},
            ]}>
            YAYYY !!!
          </Text>
          <Image
            source={
              typeof route.andieImage === 'string'
                ? {uri: route.andieImage}
                : route.andieImage
            }
            style={{height: scale(200), width: scale(200)}}
            resizeMode="contain"
          />
        </ImageBackground>
        <BookView
          style={styles.achievementContainer}
          contentStyle={styles.content}
          colorBg={route.colorBgBookView}
          imageBackground={assets.bee_bg}>
          <View style={styles.achievementContent}>
            <View style={styles.backgroundStar}>
              <Image
                source={assets.achievement_icon_new}
                resizeMode="contain"
                style={{height: '100%', width: '100%'}}
              />
            </View>
            <View style={styles.wrapperContent}>
              <Text style={[styleHook.txtModule, styles.contentTitle]}>
                {route.title} !!!
              </Text>
              <Text
                style={[styleHook.txtNote, styles.contentDescription]}
                textBreakStrategy="balanced">
                {i18n.t('lesson.screens.Modules.goodJobAgain')}{' '}
                {route.countTime && (
                  <Text style={[{fontFamily: FontFamily.SVNNeuzeitBold}]}>
                    {route.countTime ?? ''} {'\n'}
                  </Text>
                )}
                {route.note}
              </Text>
            </View>
            {route.isMiniTest && ( // * nếu là mini test thì show số hoa
              <View style={styles.wrapStarContainer}>
                <Image
                  source={assets.untitled_artwork}
                  style={styles.star}
                  resizeMode="contain"
                />
                <Text style={styles.starText}>{1}</Text>
              </View>
            )}
          </View>
          <View style={styles.wrapperButton}>
            <TouchableOpacity
              disabled={ggadsHook.isFetching}
              onPress={onNext}
              style={[styles.button, {backgroundColor: route.colorBgBookView}]}>
              <Text style={[styleHook.txtButton, styles.textBtn]}>
                {i18n.t('lesson.screens.Modules.next')}
              </Text>
              {ggadsHook.isFetching && <ActivityIndicator />}
            </TouchableOpacity>
          </View>
        </BookView>
        {isShowOnBoard && (
          <Animated.View
            entering={FadeIn.duration(200).easing(Easing.ease)}
            style={styles.absoluteContent}>
            <OnBoardingMinitestScreen />
          </Animated.View>
        )}
        {isShowWatchAds && (
          <View style={styles.absoluteContent}>
            <WatchAddScreen
              loadedAds={!!ggadsHook.loaded}
              onWatchRewardAds={onWatchRewardAds}
            />
          </View>
        )}
        {isShowGotReward &&
          !isShowOnBoard && ( // * nnếu biến này true và đang ko show onboard screen thì show modal này lên
            <TouchableOpacity
              activeOpacity={1}
              onPress={() => setIsShowWatchAds(false)}
              style={[
                styles.absoluteContent,
                {backgroundColor: route.colorBgBookView},
              ]}>
              <GotRewardModal
                loadedAds={!!ggadsHook.loaded}
                onWatchRewardAds={onReceiveReward}
              />
            </TouchableOpacity>
          )}
      </View>
    </GoogleAdsmobProvider>
  );
});
export default DoneLessonScreen;

