import {StyleSheet, Text, View} from 'react-native';
import React, {
  forwardRef,
  useCallback,
  useContext,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
} from 'react';
import LessonComponent from './LessonComponent';
import PrimaryButton from '../../components/PrimaryButton';
import {FontFamily} from 'src/core/presentation/hooks/useFonts';
import useGlobalStyle from 'src/core/presentation/hooks/useGlobalStyle';
import {CanvasWriteRef} from '../../components/CanvasWrite';
import HanziWrite from '../../components/HanziWrite';
import {Task} from 'src/home/application/types/GetListQuestionResponse';
import useAuthenticationStore from 'src/authentication/presentation/stores/useAuthenticationStore';
import {scale, verticalScale} from 'react-native-size-matters';
import {
  getCorrectAnswer,
  splitChineseWithFilter,
} from 'src/core/presentation/utils';
import {useLessonStore} from '../../stores/LessonStore/useGetPostsStore';
import {useSettingLesson} from '../../hooks/useSettingLesson';
import {COLORS} from 'src/core/presentation/constants/colors';
import {TextToSpeechContext} from 'src/core/presentation/hooks/textToSpeech/TextToSpeechContext';
import {useIsFocused} from '@react-navigation/native';
import ImageMeaning from '../../components/ImageMeaning';
import useHomeStore from 'src/home/presentation/stores/useHomeStore';
import {useI18n} from 'src/core/presentation/hooks/useI18n';
import VoiceButton from '../../components/VoiceButton';

type Props = {
  moduleIndex: number;
  totalModule: number;
  nextModule: (e: string) => void;
  lessonName: string;
  moduleName: string;
  firstMiniTestTask?: Task;
  backgroundImage?: string;
  characterImageSuccess?: string;
  characterImageFail?: string;
};

type Mandarin_G2M25Ref = {
  onChoiceCorrectedAnswer: () => void;
};

const Mandarin_G2M25 = forwardRef<Mandarin_G2M25Ref, Props>(
  (
    {
      moduleIndex,
      nextModule,
      totalModule,
      lessonName,
      moduleName,
      firstMiniTestTask,
      backgroundImage,
      characterImageFail,
      characterImageSuccess,
    }: Props,
    ref,
  ) => {
    const globalStyle = useGlobalStyle();
    const canvasWriteRef = useRef<CanvasWriteRef>(null);
    const {selectedChild} = useAuthenticationStore();
    const [answerSelected, setAnswerSelected] = useState('');
    const {trainingCount, getSetting} = useLessonStore();
    const [isCorrect, setIscorrect] = useState(false);

    const i18n = useI18n();

    const {ttsSpeak} = useContext(TextToSpeechContext);
    const focus = useIsFocused();
    const {lessonSetting} = useHomeStore();

    const settings = useMemo(
      () => getSetting(lessonSetting),
      [getSetting, lessonSetting],
    );

    const {isAnswerCorrect, isShowCorrectContainer, transDescription, submit} =
      useSettingLesson({
        countDownTime: trainingCount <= 2 ? 0 : 5,
        isCorrectAnswer: !!isCorrect,
        onSubmit: () => {
          setAnswerSelected('');
          nextModule(answerSelected);
          setIscorrect(false);
        },
        firstMiniTestTask,
        moduleIndex,
        fullAnswer: firstMiniTestTask?.question?.[moduleIndex].fullAnswer,
        totalTime: 5 * 60, // * tổng time làm 1câu
      });

    const characterImage = useMemo(() => {
      return isAnswerCorrect === true || isAnswerCorrect === undefined
        ? characterImageSuccess
        : characterImageFail;
    }, [characterImageFail, characterImageSuccess, isAnswerCorrect]);

    const onSpeechText = useCallback(() => {
      ttsSpeak?.(
        getCorrectAnswer(
          firstMiniTestTask?.question?.[
            moduleIndex
          ].correctAnswer?.toString() ?? '',
        ),
      );
    }, [firstMiniTestTask?.question, moduleIndex, ttsSpeak]);

    useEffect(() => {
      if (focus) {
        // Check if the component is focused

        const firstTimeout = setTimeout(() => {
          onSpeechText();

          const secondTimeout = setTimeout(() => {
            onSpeechText();
          }, 2500);

          return () => clearTimeout(secondTimeout);
        }, 1500);

        return () => clearTimeout(firstTimeout);
      }
    }, [onSpeechText, focus]); // Added focus to the dependency array

    useImperativeHandle(ref, () => ({
      //
      onChoiceCorrectedAnswer: () => {
        setIscorrect(true);
      },
    }));

    return (
      <LessonComponent
        backgroundImage={backgroundImage}
        characterImage={characterImage}
        lessonName={lessonName}
        module={moduleName}
        part={firstMiniTestTask?.name}
        backgroundColor="#66c270"
        backgroundAnswerColor={settings.backgroundAnswerColor}
        prompt={
          firstMiniTestTask?.question?.[moduleIndex]?.instruction ?? {
            description: settings.prompt?.toString() ?? '',
          }
        }
        score={selectedChild?.adsPoints}
        isAnswerCorrect={isAnswerCorrect}
        isShowCorrectContainer={isShowCorrectContainer}
        buildQuestion={
          <View>
            <Text style={[styles.fonts_NeuzeitBold, styles.textQuestion]}>
              {firstMiniTestTask?.question?.[moduleIndex].content}
            </Text>
            <Text style={[styles.fonts_Neuzeit, styles.textQuestion2]}>
              {transDescription}
            </Text>

            <ImageMeaning
              descriptionImage={
                firstMiniTestTask?.question?.[moduleIndex].descriptionImage
              }
              image={firstMiniTestTask?.question?.[moduleIndex].image}
            />
          </View>
        }
        buildAnswer={
          <View style={styles.fill}>
            <View
              style={{
                justifyContent: 'space-between',
                flexDirection: 'row',
              }}>
              <Text style={[globalStyle.txtLabel]}>
                {i18n.t('lesson.screens.Modules.writeThe')} "
                {firstMiniTestTask?.question?.[moduleIndex].answers}"
              </Text>
              <VoiceButton onPress={onSpeechText} />
            </View>

            <View style={{height: verticalScale(10)}} />
            <View
              style={{
                flex: 1,
                flexDirection: 'row',
                backgroundColor: COLORS.WHITE_FBF8CC,
                borderRadius: scale(30),
              }}>
              {splitChineseWithFilter(
                firstMiniTestTask?.question?.[
                  moduleIndex
                ]?.answers?.toString() ?? '',
              )?.map((item, index) => (
                <HanziWrite
                  key={index}
                  ref={canvasWriteRef}
                  text={{
                    content: item,
                    color: COLORS.PRIMARY,
                  }}
                  // eslint-disable-next-line @typescript-eslint/no-unused-vars
                  onComplete={totalMistakes => {
                    setIscorrect(true);
                  }}
                />
              ))}
            </View>
            <PrimaryButton
              text={i18n.t('lesson.screens.Modules.submit')}
              style={[
                styles.buttonContainer,
                {backgroundColor: settings.backgroundButtonColor},
              ]}
              onPress={submit}
            />
          </View>
        }
        moduleIndex={moduleIndex}
        totalModule={totalModule}
      />
    );
  },
);

export default Mandarin_G2M25;

const styles = StyleSheet.create({
  fill: {
    flex: 1,
  },
  fonts_SVN_Cherish: {
    fontFamily: FontFamily.SVNCherishMoment,
  },
  fonts_NeuzeitBold: {
    fontFamily: FontFamily.SVNNeuzeitBold,
  },
  fonts_Neuzeit: {
    fontFamily: FontFamily.SVNNeuzeitRegular,
  },
  textLarge: {
    fontSize: 140,
    textAlign: 'center',
    color: 'white',
  },
  textQuestion: {
    fontSize: scale(32),
    textAlign: 'center',
    color: COLORS.RED_811010,
  },
  textQuestion2: {
    fontSize: scale(20),
    textAlign: 'center',
    color: COLORS.RED_811010,
  },

  buttonContainer: {
    borderRadius: scale(52),
    paddingVertical: verticalScale(9),
    paddingHorizontal: scale(24),
    marginTop: scale(16),
    backgroundColor: '#0877B6',
  },
});
